public static string ExtractTokenFromResponse(HttpResponseMessage response)
{
    try
    {
        if (response.IsSuccessStatusCode)
        {
            var content = response.Content.ReadAsStringAsync().Result;
            var jsonDocument = JsonDocument.Parse(content);

            if (jsonDocument.RootElement.TryGetProperty("token", out var tokenElement))
            {
                return tokenElement.GetString() ?? string.Empty;
            }
            else if (jsonDocument.RootElement.TryGetProperty("access_token", out var accessTokenElement))
            {
                return accessTokenElement.GetString() ?? string.Empty;
            }
        }

        return string.Empty;
    }
    catch (Exception ex)
    {
        throw new ApplicationException($"Error extracting token: {ex.Message}", ex);
    }
}

