public static async Task<string> stripeTestToken()
{
    // Reads your Stripe TEST secret key from the STRIPE_TEST_KEY environment variable.
    // NEVER hardcode a secret key in source. Set it once in your shell / CI:
    //   Windows (PowerShell):  setx STRIPE_TEST_KEY "sk_test_xxx"
    //   macOS/Linux:           export STRIPE_TEST_KEY=sk_test_xxx
    var key = Environment.GetEnvironmentVariable("STRIPE_TEST_KEY");
    if (string.IsNullOrEmpty(key))
        throw new InvalidOperationException("Set the STRIPE_TEST_KEY environment variable to your Stripe test secret key.");
    return await Task.FromResult(key);
}

