public static string FormUrlEncode(object obj)
{
    var pairs = new System.Collections.Generic.List<string>();
    void Flatten(string prefix, object value)
    {
        if (value == null) return;
        if (value is bool b) { pairs.Add($"{prefix}={(b ? "true" : "false")}"); return; }
        if (value is string || value.GetType().IsPrimitive || value is decimal)
        {
            var s = System.Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture) ?? string.Empty;
            pairs.Add($"{prefix}={Uri.EscapeDataString(s)}");
            return;
        }
        if (value is System.Collections.IDictionary dict)
        {
            foreach (System.Collections.DictionaryEntry de in dict) { Flatten($"{prefix}[{de.Key}]", de.Value); }
            return;
        }
        if (value is System.Collections.IEnumerable list)
        {
            int i = 0;
            foreach (var item in list) { Flatten($"{prefix}[{i}]", item); i++; }
            return;
        }
        foreach (var p in value.GetType().GetProperties())
        {
            var attr = (System.Text.Json.Serialization.JsonPropertyNameAttribute)System.Attribute.GetCustomAttribute(p, typeof(System.Text.Json.Serialization.JsonPropertyNameAttribute));
            var name = attr != null ? attr.Name : p.Name;
            var key = string.IsNullOrEmpty(prefix) ? name : $"{prefix}[{name}]";
            Flatten(key, p.GetValue(value));
        }
    }
    Flatten(string.Empty, obj);
    return string.Join("&", pairs);
}

public static async Task<string> ExtractFieldFromResponse(HttpResponseMessage response, string fieldPath)
{
    // Validates the response (200 or 201) then returns a value from the JSON body by path — so a
    // create step needs no separate validate. Supports nested objects and array indices using dot
    // and/or bracket notation, e.g. "id", "data.id", "data[0].id", "items.0.customer.id".
    var status = (int)response.StatusCode;
    var passed = status == 200 || status == 201;
    Console.WriteLine(passed ? $"PASS: status {status}" : $"FAIL: expected 200 or 201 but got {status}");
    if (!passed) { throw new Exception($"Response validation failed: expected 200 or 201 but got {status}."); }
    var body = await response.Content.ReadAsStringAsync();
    using (var doc = JsonDocument.Parse(body))
    {
        var element = doc.RootElement;
        foreach (var raw in fieldPath.Split('.'))
        {
            var seg = raw.Trim();
            if (seg.Length == 0) { continue; }

            var name = seg;
            var indices = new System.Collections.Generic.List<int>();
            var bracket = seg.IndexOf('[');
            if (bracket >= 0)
            {
                name = seg.Substring(0, bracket);
                foreach (System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(seg, @"\[(\d+)\]"))
                {
                    indices.Add(int.Parse(match.Groups[1].Value));
                }
            }

            if (name.Length > 0)
            {
                if (element.ValueKind == JsonValueKind.Array && int.TryParse(name, out var dotIndex))
                {
                    if (dotIndex >= element.GetArrayLength()) { throw new Exception($"Array index '{dotIndex}' is out of range in the response body."); }
                    element = element[dotIndex];
                }
                else if (element.ValueKind == JsonValueKind.Object && element.TryGetProperty(name, out var next))
                {
                    element = next;
                }
                else
                {
                    throw new Exception($"Path segment '{name}' not found in the response body.");
                }
            }

            foreach (var idx in indices)
            {
                if (element.ValueKind != JsonValueKind.Array || idx >= element.GetArrayLength()) { throw new Exception($"Array index '[{idx}]' is out of range in the response body."); }
                element = element[idx];
            }
        }

        return element.ValueKind == JsonValueKind.String ? element.GetString() : element.ToString();
    }
}

