public static async Task<HttpResponseMessage> DeleteByParamAsync(string token, string urlTemplate, string value)
{
    // Replace the first {..} placeholder (id, customer, account, ...) with the captured value.
    var url = System.Text.RegularExpressions.Regex.Replace(urlTemplate, @"\{[^}]+\}", Uri.EscapeDataString(value));
    using (var client = new HttpClient())
    using (var request = new HttpRequestMessage(HttpMethod.Delete, url))
    {
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);
        request.Headers.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));
        var response = await client.SendAsync(request);
        return Reporter.Record("DELETE", url, null, response);
    }
}

